  ["faceoffScreen","faceoffProgress","faceoffHeading","faceoffPlayerPortrait","faceoffCpuPortrait","faceoffPlayerName","faceoffCpuName","faceoffCpuRole","campaignRoute","faceoffContinue","faceoffTimer","fightProgress","cpuRole","championCelebration","championPortrait","championSubtitle"].forEach(id => { ui[id] = $(id); });
